export interface PatientInput {
  adjuvant_therapy_using_biological_drugs: number;
  radiotherapy_rt_performed: number;
  radiotherapy_on_supraclavicular_area: number;
  endocrine_therapy_performed: number;
  treatment_in_association_with_chemotherapy: number;
  side_location_of_the_lesion: number;
  total_administered_dose: number;
  grade_at_cb: string;
  n_regional_nodes_affected: string;
  oestrogen_receptor_status_at_cb: string;
  her2_overexpression_with_immunohystochemistry_at_cb: string;
  isotype_at_cb: string;
}

export const DEFAULT_INPUT: PatientInput = {
  adjuvant_therapy_using_biological_drugs: 0,
  radiotherapy_rt_performed: 0,
  radiotherapy_on_supraclavicular_area: 0,
  endocrine_therapy_performed: 0,
  treatment_in_association_with_chemotherapy: 0,
  side_location_of_the_lesion: 0,
  total_administered_dose: 0.0,
  grade_at_cb: "1",
  n_regional_nodes_affected: "0",
  oestrogen_receptor_status_at_cb: "unknown",
  her2_overexpression_with_immunohystochemistry_at_cb: "unknown",
  isotype_at_cb: "1",
};

export const REPORT_YEARS = [1,2,3,4,5];
export const REPORT_DAYS = [365,730,1095,1460,1825];

function scaleFeature(value: number, scalerScale: number, scalerMin: number): number {
  return value * scalerScale + scalerMin;
}

export interface FeatureContribution {
  name: string;
  coefficient: number;
  scaledValue: number;
  contribution: number;
}

export type RiskCategory = "low" | "intermediate" | "average" | "high";

export function getRiskCategory(risk: number, timeIndex: number): RiskCategory {
  if (timeIndex < 0 || timeIndex >= THRESHOLD_LOW.length) return "average";
  if (risk <= THRESHOLD_LOW[timeIndex]) return "low";
  if (risk <= THRESHOLD_AVERAGE[timeIndex]) return "intermediate";
  if (risk < THRESHOLD_HIGH[timeIndex]) return "average";
  if (risk >= THRESHOLD_HIGH[timeIndex]) return "high";
  return "average";
}

function getRawValue(input: PatientInput, spec: FeatureSpec): number {
  if (spec.oheSuffix === undefined) {
    const value = input[spec.inputKey as keyof PatientInput];
    return Number(value ?? spec.dataMin);
  }
  const v = String(input[spec.inputKey as keyof PatientInput]);
  const s = spec.oheSuffix;
  switch (spec.inputKey) {
    case "grade_at_cb":
      if (v === "unknown") return 0;
      if (s === "2.0") return v === "2" ? 1 : 0;
      if (s === "3.0") return v === "3" ? 1 : 0;
      return 0;
    case "her2_overexpression_with_immunohystochemistry_at_cb":
      if (v === "unknown") return 0;
      if (s === "1.0") return v === "1" ? 1 : 0;
      if (s === "2.0") return v === "2" ? 1 : 0;
      if (s === "3.0") return v === "3" ? 1 : 0;
      return 0;
    case "isotype_at_cb":
      if (v === "unknown") return 0;
            if (s === "2.0") return v === "2" ? 1 : 0;
            if (s === "3.0") return v === "3" ? 1 : 0;
            if (s === "4.0") return v === "4" ? 1 : 0;
            return 0;
    case "n_regional_nodes_affected":
      if (v === "0") return 0;
      if (s === "1.0") return v === "1" ? 1 : 0;
        if (s === "23.0") return v === "23" ? 1 : 0;
      return 0;
    case "oestrogen_receptor_status_at_cb":
      if (v === "unknown") return 0;
      if (s === "0.0") return v === "0" ? 1 : 0;
      if (s === "1.0") return v === "1" ? 1 : 0;
      return 0;
    default:
      return 0;
  }
}

export function computeRisk(input: PatientInput) {
  const contributions: FeatureContribution[] = [];
  let linearPredictor = 0;

  for (const spec of FEATURES) {
    const rawValue = getRawValue(input, spec);
    const scaled = scaleFeature(rawValue, spec.scalerScale, spec.scalerMin);
    const contribution = spec.coef * scaled;
    linearPredictor += contribution;

    const displayName = spec.groupName || spec.name;
    const existing = contributions.find((c) => c.name === displayName);
    if (existing) {
      existing.contribution += contribution;
      existing.scaledValue = Math.max(existing.scaledValue, scaled);
    } else {
      contributions.push({ name: displayName, coefficient: spec.coef, scaledValue: scaled, contribution });
    }
  }

  contributions.sort((a, b) => Math.abs(b.contribution) - Math.abs(a.contribution));
  const expFactor = Math.exp(linearPredictor - MODEL_OFFSET);

  const survivalCurve = BASELINE_TIMES.map((t, i) => {
    const H0 = BASELINE_CUM_HAZARDS[i];
    const survival = Math.exp(-H0 * expFactor);
    const risk = 1 - survival;
    return {
      time: t,
      survival,
      risk,
      thresholdLow: THRESHOLD_LOW[i],
      thresholdHigh: THRESHOLD_HIGH[i],
      thresholdAverage: THRESHOLD_AVERAGE[i],
      category: getRiskCategory(risk, i),
    };
  });

  const yearlyRisk = REPORT_DAYS.map((days, i) => {
    const idx = Math.min(Math.floor(days / 5), BASELINE_TIMES.length - 1);
    const H0 = BASELINE_CUM_HAZARDS[idx];
    const survival = Math.exp(-H0 * expFactor);
    const risk = 1 - survival;
    return {
      year: REPORT_YEARS[i],
      survival,
      risk,
      thresholdLow: THRESHOLD_LOW[idx],
      thresholdHigh: THRESHOLD_HIGH[idx],
      thresholdAverage: THRESHOLD_AVERAGE[idx],
      category: getRiskCategory(risk, idx),
    };
  });

  return { survivalCurve, contributions, yearlyRisk, linearPredictor };
}

